package org.example;
import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
public class Order { private final int orderID; private final Customer customer; private final List<Item> items=new ArrayList<>(); private final List<OrderObserver> observers=new ArrayList<>(); private final String createdAt=LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")); private OrderState state=new PendingState(); private PaymentMethod payment; private boolean paid;
 public Order(int id,Customer c){orderID=id;customer=c;} public int getOrderID(){return orderID;} public Customer getCustomer(){return customer;} public String getCreatedAt(){return createdAt;} public String getStatus(){return state.label();} public double getTotal(){return calculateTotal();} public List<Item> getItems(){return Collections.unmodifiableList(items);} public boolean isEmpty(){return items.isEmpty();} public boolean isPaid(){return paid;} public PaymentMethod getPayment(){return payment;}
 public void addItem(Item i){if(!(state instanceof PendingState))throw new IllegalStateException("This cart is no longer editable."); Objects.requireNonNull(i); if(i.getStock()<1)throw new IllegalStateException("This item is out of stock."); items.add(i);} public void removeItemAt(int i){if(!(state instanceof PendingState))throw new IllegalStateException("This cart is no longer editable."); if(i<0||i>=items.size())throw new IllegalArgumentException("Select an item in the cart first.");items.remove(i);} public double calculateTotal(){return items.stream().mapToDouble(Item::getPrice).sum();} public void setPayment(PaymentMethod p){payment=p;}
 public void checkout(){if(items.isEmpty())throw new IllegalStateException("Your cart is empty.");if(payment==null)throw new IllegalStateException("Choose a payment method.");Map<Item, Long> quantities = new IdentityHashMap<>(); for (Item i : items) quantities.merge(i, 1L, Long::sum); for (Map.Entry<Item, Long> entry : quantities.entrySet()) { if (entry.getKey().getStock() < entry.getValue()) throw new IllegalStateException("Insufficient stock for: " + entry.getKey().getTitle() + " (available: " + entry.getKey().getStock() + ")"); } if(!payment.processPayment(calculateTotal()))throw new IllegalStateException("Payment failed."); for (Map.Entry<Item, Long> entry : quantities.entrySet()) entry.getKey().reduceStock(Math.toIntExact(entry.getValue())); paid=true;transition(state.next());}
 public void advanceStatus(){if(!paid)throw new IllegalStateException("Checkout first.");transition(state.next());} public void cancel(){if(paid)throw new IllegalStateException("Paid orders cannot be cancelled in this demo.");transition(state.cancel());} public void addObserver(OrderObserver o){if(o!=null&&!observers.contains(o))observers.add(o);} public void removeObserver(OrderObserver o){observers.remove(o);} private void transition(OrderState next){String old=state.label();state=next;for(OrderObserver o:List.copyOf(observers))o.onOrderStatusChanged(this,old,state.label());}
}